import logging
import os
from typing import Any, Dict, Optional

from anthropic import Anthropic
from openai import OpenAI


class LLMService:
    def __init__(self):
        self.openai_client = None
        self.anthropic_client = None
        self._initialize_clients()

    def _initialize_clients(self):
        """Initialize LLM clients based on available API keys"""
        openai_key = os.getenv("OPENAI_API_KEY")
        anthropic_key = os.getenv("ANTHROPIC_API_KEY")

        if openai_key:
            try:
                self.openai_client = OpenAI(api_key=openai_key)
                logging.info("OpenAI client initialized successfully")
            except Exception as e:
                logging.error(f"Failed to initialize OpenAI client: {e}")

        if anthropic_key:
            try:
                # Initialize Anthropic client (compatible with latest SDK)
                self.anthropic_client = Anthropic(api_key=anthropic_key)
                logging.info("Anthropic client initialized successfully")
            except TypeError as e:
                # Handle version compatibility issues
                if "proxies" in str(e):
                    logging.warning(f"Anthropic SDK version mismatch, trying alternative initialization: {e}")
                    try:
                        # Try without any extra parameters
                        import anthropic
                        self.anthropic_client = anthropic.Anthropic(api_key=anthropic_key)
                        logging.info("Anthropic client initialized successfully (alternative method)")
                    except Exception as e2:
                        logging.error(f"Failed to initialize Anthropic client: {e2}")
                else:
                    logging.error(f"Failed to initialize Anthropic client: {e}")
            except Exception as e:
                logging.error(f"Failed to initialize Anthropic client: {e}")

        if not self.openai_client and not self.anthropic_client:
            logging.warning("No LLM clients available - check API keys in .env file")

    def call_llm(
        self, prompt: str, provider: Optional[str] = None, model: Optional[str] = None
    ) -> Dict[str, Any]:
        """
        Call LLM with automatic fallback between providers

        Args:
            prompt: The prompt to send to the LLM
            provider: Preferred provider ('openai' or 'anthropic'). If None, uses first available
            model: Specific model to use. If None, uses default for provider

        Returns:
            Dict with 'content', 'provider', and 'error' keys
        """
        # Determine provider order
        if provider == "anthropic" and self.anthropic_client:
            providers_to_try = [("anthropic", self.anthropic_client)]
            if self.openai_client:
                providers_to_try.append(("openai", self.openai_client))
        elif provider == "openai" and self.openai_client:
            providers_to_try = [("openai", self.openai_client)]
            if self.anthropic_client:
                providers_to_try.append(("anthropic", self.anthropic_client))
        else:
            # Default order: try openai first, then anthropic
            providers_to_try = []
            if self.openai_client:
                providers_to_try.append(("openai", self.openai_client))
            if self.anthropic_client:
                providers_to_try.append(("anthropic", self.anthropic_client))

        if not providers_to_try:
            return {
                "content": "",
                "provider": None,
                "error": "No LLM providers available",
            }

        # Try each provider
        for provider_name, client in providers_to_try:
            try:
                logging.info(f"Attempting LLM call with {provider_name}")

                if provider_name == "anthropic":
                    response = self._call_anthropic(client, prompt, model)
                else:  # openai
                    response = self._call_openai(client, prompt, model)

                logging.info(f"Successfully called {provider_name}")
                return {"content": response, "provider": provider_name, "error": None}

            except Exception as e:
                logging.error(f"Failed to call {provider_name}: {e}")
                continue

        return {"content": "", "provider": None, "error": "All LLM providers failed"}

    def _call_anthropic(
        self, client: Anthropic, prompt: str, model: Optional[str] = None
    ) -> str:
        """Call Anthropic Claude API"""
        if not model:
            model = "claude-3-5-sonnet-20241022"

        response = client.messages.create(
            model=model, max_tokens=8000, messages=[{"role": "user", "content": prompt}]
        )

        return response.content[0].text

    def _call_openai(
        self, client: OpenAI, prompt: str, model: Optional[str] = None
    ) -> str:
        """Call OpenAI GPT API"""
        if not model:
            model = "gpt-5"

        # Check if this is GPT-5 and use the new API
        if model == "gpt-5":
            response = client.responses.create(
                model=model,
                reasoning={"effort": "medium"},
                input=[{"role": "user", "content": prompt}],
            )
            return response.output_text
        else:
            # Use traditional API for GPT-4 and older models
            response = client.chat.completions.create(
                model=model,
                messages=[{"role": "user", "content": prompt}],
                max_tokens=12000,
            )
            return response.choices[0].message.content


# Global service instance
llm_service = LLMService()
